message.content:
{
  "gate_token": "XrYxkU-4s8--jwEOEsxjAg",
  "title": "The Mirror Road Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds her map at the broken city's edge.",
      "visual_description": "A windswept overlook above a ruined royal city at dusk, tattered banners flapping on distant spires. A coated figure kneels with a brass compass over a hand-drawn map weighted by stones.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "Close-up of a brass oil lamp held aloft, a single eye burning inside its flame, casting a long worried shadow across cracked cobblestones and a crumbling gate.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the rubble-strewn approach.",
      "visual_description": "A small clockwork fox with a key-wind tail and blue glass eyes darts between fallen statues, gears clicking softly under a violet twilight sky.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver arrives by stepping out of a shop window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall cracked storefront window as if surfacing from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They debate which temptation to ignore first.",
      "visual_description": "Four companions huddled in an alley, the lamp's eye throwing light on a map dotted with castle gates, a cursed tower, and rumored lair markings.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol stomps past, missing them.",
      "visual_description": "From a low gutter view, polished boots and pike-butts thud by overhead while a clockwork fox crouches flat behind a barrel, blue eyes dimmed.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower beckons with false treasure-light.",
      "visual_description": "A leaning black tower glows green from slit windows; floating coins and crowns drift in the air outside it. The lamp's eye narrows in disapproval.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara redraws the route to avoid the tower entirely.",
      "visual_description": "Ink bleeding across vellum as a gloved hand draws a new red line skirting wide around the tower, brass compass spinning beside a steaming tin cup.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector slumped in a kiosk.",
      "visual_description": "A toll booth full of stamped papers, an official snoring with a ledger as a pillow, official seals stuck comically to his sleeves and cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The lamp warns: do not wake him, do not pay him.",
      "visual_description": "The oracle lamp tilts close to the sleeper's ear, its flame-eye wide with alarm; Mara holds a coin back at arm's length.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver slips through a tall stained-glass door.",
      "visual_description": "A figure in a diving helmet wades shoulder-deep into a glowing cathedral window as if it were water, ripples spreading across colored glass saints.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "On the other side: a locked magic door pulses red.",
      "visual_description": "Inside a vaulted hall, a heavy iron door glows with rotating sigils; the diver's reflection multiplies across its polished surface.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox picks the lock with a wound-up tail.",
      "visual_description": "Close-up: a clockwork fox jams its slim copper key-tail into a glowing keyhole, sparks dancing along its whiskers.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive curled in a chalk circle.",
      "visual_description": "A dim cell with a chalk binding circle on the floor; the sleeping tax collector is dragged in, blinking, while Mara kneels to break the chalk line.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "An alarm horn sounds across the ruined city.",
      "visual_description": "Through a shattered window, distant towers light up one by one with red beacons; banners snap in a sudden wind as the lamp's eye flares.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox leads them through mirrored back-alleys.",
      "visual_description": "Narrow lanes lined with hanging mirror shards reflect the running party into a hundred copies; the fox sprints ahead, tail whirring.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint onto the long bridge out of the city.",
      "visual_description": "A vast moonlit stone bridge over a black river, the broken skyline behind them; four companions and a half-awake official pelt across cracked flagstones.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, Mara marks the route as closed.",
      "visual_description": "Dawn over rolling hills; the cartographer stamps a red X across the city on her map while the lamp dims to a soft ember and the fox folds neatly into sleep.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

